import test from"node:test";import assert from"node:assert/strict";import{createHash}from"node:crypto";import{buildGovernanceWorkReceipt as receipt}from"../src/governance-work-receipt.js";import{buildGovernanceCiProof as proof}from"../src/governance-ci-proof.js";import{buildGovernanceReceiptBundle as bundle}from"../src/governance-receipt-bundle.js";import{buildGovernanceMissingReceiptReport as missing}from"../src/governance-missing-receipt-report.js";const h=x=>createHash("sha256").update(x).digest("hex"),run=()=>{let r=receipt({taskId:"T1",lane:"instinct",mergeHash:"abcdef0",outcome:"completed",observedAt:"2026-09-17T01:00:00Z"}),p=proof({receiptHash:r.receiptHash,checkCodes:["TEST","EXFIL"],commitHash:h("commit"),passed:true}),b=bundle({receipts:[r],proofs:[p]}),m=missing({completedTaskIds:["T1"],receipts:[r]});return{r,p,b,m}};test("566 done requires receipt and green CI proof",()=>{let a=run(),b=run();assert.deepEqual(a,b);assert.equal(a.m.complete,true);assert.ok(Object.isFrozen(a.b.proofs));assert.match(a.b.bundleHash,/^[a-f0-9]{64}$/)});test("566 missing receipt and failed proof cannot bundle",()=>{let a=run(),m=missing({completedTaskIds:["T1","T2"],receipts:[a.r]});assert.deepEqual(m.missing,["T2"]);assert.throws(()=>bundle({receipts:[a.r],proofs:[{...a.p,passed:false}]}),/bundle/)});